+    assert!(near(m[1].to.x - a.center.x, 0.0));
+    let (rx, ry) = (m[2].to.x - a.center.x, m[2].to.y - a.center.y);
+    assert!(
+        near(rx * s + ry * s, 0.0),
+        "radius is normal to the line after"
+    );
+}
